from svg import box, t, arrow, svg

NODES = [(475, 20, 'A REAL HARM', 'a family loses a child'), (860, 120, 'A VIVID STORY', 'told with certainty'),
         (760, 300, 'A SURE EXPERT', 'a name for it'), (190, 300, 'A MEDIA WAVE', 'more stories arrive'),
         (90, 120, 'A METHOD', 'finds what it seeks')]
FIG = svg(1180, 420, 'The panic engine: how a real harm becomes a moral panic',
          ''.join(box(x, y, 230, 86, 's-box-a' if i == 0 else 's-card') + t(x + 115, y + 36, a, 's-t') + t(x + 115, y + 66, b, 's-t-sm')
                  for i, (x, y, a, b) in enumerate(NODES)) +
          arrow(705, 63, 860, 140, True) + arrow(960, 206, 900, 300) + arrow(760, 343, 420, 343) + arrow(250, 300, 210, 206) +
          arrow(320, 140, 475, 70, True) +
          t(590, 190, 'the loop', 's-t-d') + t(590, 222, 'each turn adds more cases', 's-t-sm') +
          t(590, 410, 'The way out of the loop: ask what was documented, by whom, and what would count against it', 's-t-sm'))

